/** Fixed local interactive demo stories; never generated by AI or sent to chat. */
export interface StoryGiftChoice {
  id: string
  label: string
  response: string
}

export interface StoryGiftEvent {
  id: string
  title: string
  intro: string
  choices: readonly [Readonly<StoryGiftChoice>, Readonly<StoryGiftChoice>]
}

function fixedEvent(event: StoryGiftEvent): Readonly<StoryGiftEvent> {
  return Object.freeze({
    ...event,
    choices: Object.freeze(event.choices.map(choice => Object.freeze(choice))) as StoryGiftEvent['choices'],
  })
}

